class Parser {
public:
    string s;
    int pos;

    Parser(const string& str) : s(str), pos(0) {}

    void skipSpaces() {
        while (pos < (int)s.size() && isspace((unsigned char)s[pos])) pos++;
    }

    long long parseExpression() {
        long long val = parseTerm();
        while (true) {
            skipSpaces();
            if (pos >= (int)s.size()) break;
            char op = s[pos];
            if (op != '+' && op != '-') break;
            pos++;
            long long rhs = parseTerm();
            if (op == '+') val += rhs;
            else val -= rhs;
        }
        return val;
    }

    long long parseTerm() {
        long long val = parseFactor();
        while (true) {
            skipSpaces();
            if (pos >= (int)s.size()) break;
            char op = s[pos];
            if (op != '*' && op != '/') break;
            pos++;
            long long rhs = parseFactor();
            if (op == '*') val *= rhs;
            else val /= rhs; // integer division truncates toward zero in C++
        }
        return val;
    }

    long long parseFactor() {
        skipSpaces();

        if (s[pos] == '(') {
            pos++;
            long long val = parseExpression();
            skipSpaces();
            if (pos < (int)s.size() && s[pos] == ')') pos++;
            return val;
        }

        // handle unary +/-
        int sign = 1;
        while (pos < (int)s.size() && (s[pos] == '+' || s[pos] == '-')) {
            if (s[pos] == '-') sign = -sign;
            pos++;
            skipSpaces();
        }

        if (pos < (int)s.size() && s[pos] == '(') {
            pos++;
            long long val = parseExpression();
            skipSpaces();
            if (pos < (int)s.size() && s[pos] == ')') pos++;
            return sign * val;
        }

        long long num = 0;
        while (pos < (int)s.size() && isdigit((unsigned char)s[pos])) {
            num = num * 10 + (s[pos] - '0');
            pos++;
        }
        return sign * num;
    }
};

