    static long parseExpr() {
        long result = parseTerm();
        while (pos < expr.length()) {
            char op = expr.charAt(pos);
            if (op == '+' || op == '-') {
                pos++;
                long term = parseTerm();
                if (op == '+') result += term;
                else result -= term;
            } else {
                break;
            }
        }
        return result;
    }

    static long parseTerm() {
        long result = parseFactor();
        while (pos < expr.length()) {
            char op = expr.charAt(pos);
            if (op == '*' || op == '/') {
                pos++;
                long factor = parseFactor();
                if (op == '*') result *= factor;
                else result = (long)(result / factor); // truncate toward zero
            } else {
                break;
            }
        }
        return result;
    }

    static long parseFactor() {
        // Skip whitespace
        while (pos < expr.length() && expr.charAt(pos) == ' ') pos++;

        if (pos >= expr.length()) return 0;

        char c = expr.charAt(pos);

        if (c == '(') {
            pos++; // consume '('
            long result = parseExpr();
            if (pos < expr.length() && expr.charAt(pos) == ')') {
                pos++; // consume ')'
            }
            return result;
        } else if (c == '-') {
            pos++;
            long val = parseFactor();
            return -val;
        } else if (c == '+') {
            pos++;
            return parseFactor();
        } else if (Character.isDigit(c)) {
            long num = 0;
            while (pos < expr.length() && Character.isDigit(expr.charAt(pos))) {
                num = num * 10 + (expr.charAt(pos) - '0');
                pos++;
            }
            return num;
        }

        return 0;
    }
}

