def evaluate_expression(expr):
    # Remove trailing '='
    expr = expr.rstrip('=').strip()

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    # Stacks
    values = []
    ops = []

    i = 0
    while i < len(expr):
        ch = expr[i]

        if ch.isdigit() or (ch == '-' and (i == 0 or expr[i-1] in '(+*-/')):
            # It's a number (possibly negative)
            sign = 1
            if ch == '-':
                sign = -1
                i += 1
            num = 0
            while i < len(expr) and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            values.append(sign * num)
            continue
        elif ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                b = values.pop()
                a = values.pop()
                op = ops.pop()
                if op == '+':
                    values.append(a + b)
                elif op == '-':
                    values.append(a - b)
                elif op == '*':
                    values.append(a * b)
                elif op == '/':
                    values.append(a // b)  # integer division truncates toward negative infinity in Python
                                         # but problem says "truncated" — use int(a/b) to truncate toward zero
            ops.pop()  # remove '('
        elif ch in '+-*/':
            while ops and ops[-1] != '(' and precedence[ops[-1]] >= precedence[ch]:
                b = values.pop()
                a = values.pop()
                op = ops.pop()
                if op == '+':
                    values.append(a + b)
                elif op == '-':
                    values.append(a - b)
                elif op == '*':
                    values.append(a * b)
                elif op == '/':
                    values.append(int(a / b))  # truncates toward zero as required
            ops.append(ch)
        i += 1

    while ops:
        b = values.pop()
        a = values.pop()
        op = ops.pop()
        if op == '+':
            values.append(a + b)
        elif op == '-':
            values.append(a - b)
        elif op == '*':
            values.append(a * b)
        elif op == '/':
            values.append(int(a / b))

    return values[0]

